<script>
document.getElementById('ai-bilan').addEventListener('click', async () => { const button = document.getElementById('ai-bilan'), box = document.getElementById('ai-bilan-result'); button.disabled = true; box.className = 'mt-5 animate-pulse rounded-xl bg-green-50 p-5 text-green-900'; box.textContent = 'Génération de votre bilan...'; try { const response = await fetch('{{ route('impact.ai-summary') }}', { method: 'POST', headers: {'Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'} }); const data = await response.json(); box.classList.remove('animate-pulse'); box.innerHTML = '<span class="mb-2 inline-flex rounded-full bg-green-800 px-3 py-1 text-xs font-bold text-white">Texte généré par IA</span><p class="mt-2"></p>'; box.querySelector('p').textContent = data.bilan || 'Le conseiller IA est indisponible, démarrez Ollama.'; } catch { box.textContent = 'Le conseiller IA est indisponible, démarrez Ollama.'; } finally { button.disabled = false; } });
</script>
